B=$(cat $G/base); H=$(h 5); X="--org-profile {state_dir}/grant.toml"; $V 5 $H ok=none; ok 5 || exit 1
$C train check 5 $P $X | grep 'name=grant-scope status=manual' || exit 1
miss 5 'name=verdict status=blocked' ok=none verdict=$B || exit 1
miss 5 'name=ci status=blocked' ok=none ci=FAILURE || exit 1
miss 5 'name=evidence status=blocked' ok=none "body=## Testing Done" || exit 1
miss 5 'reason="state tag crew:hold"' ok=none label=crew:hold || exit 1
miss 5 'reason="open rereview at head"' ok=none "review=COMMENTED|<!-- crew:v1 role=coordinator pass=steer cmd=rereview pr=5 sha=$H -->" || exit 1
miss 5 'name=sensitive status=blocked' ok=none label=crew:sensitive || exit 1
miss 5 'merge_grant_scope does not cover spec' ok=none label=crew:spec || exit 1
X="--org-profile {state_dir}/spec.toml"; $V 5 $H ok=none label=crew:spec; ok 5 || exit 1
miss 5 'name=sensitive status=blocked' ok=none label=crew:spec label=crew:sensitive || exit 1
X="--org-profile {state_dir}/grant.toml"; k=$(train 5) && $V 5 $H ok=none && $C train land $k 5 $P $T $X | grep "^landed pr=5 " && grep -o 'merge_grant = "#9 c1"' $L | head -1 | grep .

