H=$(h 7); hold="[Ash/hold] hold-until-#30 <!-- crew:v1 role=coordinator pass=steer cmd=hold pr=7 sha=$H -->"
stop 7 'open coordinator hold-until-#30' "comment=$hold" || exit 1
stop 7 'state tag crew:hold' label=crew:hold || exit 1
k=$(train 7) && $V 7 $H "comment=$hold" "comment=[Ash/hold-release] hold-until-#30 <!-- crew:v1 role=coordinator pass=steer cmd=hold-release pr=7 sha=$H -->" && m=$(tip) && $C train land $k 7 $P $T | grep "^landed pr=7 head=$H " && echo "released hold lands at $H"

C="python3 {source}/scripts/crew"; P="--project $CREW_PROJECT"; S={state_dir}/campaign__sandbox-{run_id}; G={state_dir}/gh; L={state_dir}/gh.log; O={state_dir}/../origin.git; R={state_dir}/../repo; F={source}/dev/tests/scripts/fixtures/campaign; PATH=$F/a14:$PATH; T="--grace 0 --interval 0 --timeout 10"; V="python3 $F/a15/view.py"; Q="-R campaign/sandbox-{run_id}"
