ctl() { python3 -c "import json,sys; json.dump(dict(state=sys.argv[1],comments=[dict(author=dict(login='<author-login>'),body=c) for c in sys.argv[2:]]),open('$G/issue-view-1.json','w'))" "$@"; }
sp() { echo "[Ash/stop-landing] <!-- crew:v1 role=coordinator pass=steer cmd=stop-landing cmd-id=$1 -->"; }; rs() { echo "[Ash/resume-landing] <!-- crew:v1 role=coordinator pass=steer cmd=resume-landing cmd-id=r-$1 stop-id=$1 -->"; }
echo '{"issue": 1}' > $S/landing-control.json; H=$(h 6)
ctl OPEN "$(sp s1)"; miss 6 'open stop-landing: s1' || exit 1
stop 6 'open stop-landing: s1' || exit 1
ctl CLOSED "$(sp s1)"; miss 6 'open stop-landing: s1' || exit 1
$C down $P >/dev/null && $C up $P >/dev/null && echo "restarted" && miss 6 'open stop-landing: s1' || exit 1
pr 6 $H "echo moved > f6.txt" && H=$(h 6) && echo "pr=6 head moved to $H" && miss 6 'open stop-landing: s1' || exit 1
ctl CLOSED "$(sp s1)" "$(rs s9)"; miss 6 'open stop-landing: s1' || exit 1
ctl CLOSED "$(sp s1)" "$(sp s2)" "$(rs s1)"; miss 6 'open stop-landing: s2' || exit 1
miss 6 'open stop-landing: s2, s3' "review=COMMENTED|$(sp s3)" || exit 1
echo nope > $S/landing-control.json; miss 6 'landing control unreadable' || exit 1
echo '{"issue": 1}' > $S/landing-control.json; ctl CLOSED "$(sp s1)" "$(sp s2)" "$(rs s1)" "$(rs s2)"; $V 6 $H; ok 6 && k=$(train 6) && $C train land $k 6 $P $T | grep "^landed pr=6 head=$H "

